func ptrExport(p unsafe.Pointer, c int32) any {
	r := (*audit.Export)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.RequestedByID))
	case 4:
		return (*string)(unsafe.Pointer(&r.Format))
	case 5:
		return &r.Filters
	case 6:
		return &r.RangeFrom
	case 7:
		return &r.RangeTo
	case 8:
		return &r.IncludeSecurity
	case 9:
		return (*string)(unsafe.Pointer(&r.Status))
	case 10:
		return &r.RowCount
	case 11:
		return &r.ByteSize
	case 12:
		return &r.SHA256
	case 13:
		return &r.ArtifactKey
	case 14:
		return &r.ArtifactExpiresAt
	case 15:
		return &r.WorkflowID
	case 16:
		return &r.ErrorMessage
	case 17:
		return &r.StartedAt
	case 18:
		return &r.CompletedAt
	case 19:
		return &r.Version
	case 20:
		return &r.CreatedAt
	case 21:
		return &r.UpdatedAt
	}
	return nil
}

func valueExport(p unsafe.Pointer, c int32) any {
	r := (*audit.Export)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.RequestedByID)
	case 4:
		return string(r.Format)
	case 5:
		return r.Filters
	case 6:
		return r.RangeFrom
	case 7:
		return r.RangeTo
	case 8:
		return r.IncludeSecurity
	case 9:
		return string(r.Status)
	case 10:
		return r.RowCount
	case 11:
		return r.ByteSize
	case 12:
		if r.SHA256 == "" {
			return nil
		}
		return r.SHA256
	case 13:
		if r.ArtifactKey == "" {
			return nil
		}
		return r.ArtifactKey
	case 14:
		if r.ArtifactExpiresAt == nil {
			return nil
		}
		return *r.ArtifactExpiresAt
	case 15:
		if r.WorkflowID == "" {
			return nil
		}
		return r.WorkflowID
	case 16:
		if r.ErrorMessage == "" {
			return nil
		}
		return r.ErrorMessage
	case 17:
		if r.StartedAt == nil {
			return nil
		}
		return *r.StartedAt
	case 18:
		if r.CompletedAt == nil {
			return nil
		}
		return *r.CompletedAt
	case 19:
		return r.Version
	case 20:
		return r.CreatedAt
	case 21:
		return r.UpdatedAt
	}
	return nil
}

