func newSeal() unsafe.Pointer { return unsafe.Pointer(new(audit.Seal)) }

func newNSeal(n int) unsafe.Pointer { return unsafe.Pointer(unsafe.SliceData(make([]audit.Seal, n))) }

func ptrSeal(p unsafe.Pointer, c int32) any {
	r := (*audit.Seal)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return &r.Seq
	case 3:
		return &r.FromTS
	case 4:
		return &r.ToTS
	case 5:
		return &r.RowCount
	case 6:
		return &r.ClassDigests
	case 7:
		return &r.PrevHash
	case 8:
		return &r.Hash
	case 9:
		return &r.HashKeyID
	case 10:
		return &r.HashVersion
	case 11:
		return &r.SealedAt
	}
	return nil
}

func valueSeal(p unsafe.Pointer, c int32) any {
	r := (*audit.Seal)(p)
	switch c {
	case 0:
		return string(r.OrganizationID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return r.Seq
	case 3:
		return r.FromTS
	case 4:
		return r.ToTS
	case 5:
		return r.RowCount
	case 6:
		if r.ClassDigests == nil {
			return keel.EmptyJSONObject
		}
		return r.ClassDigests
	case 7:
		return r.PrevHash
	case 8:
		return r.Hash
	case 9:
		if r.HashKeyID == "" {
			return nil
		}
		return r.HashKeyID
	case 10:
		return r.HashVersion
	case 11:
		return r.SealedAt
	}
	return nil
}

